#!/usr/bin/env bash\nset -euo pipefail\n\nDIR="${1:-.}"\nif [[ ! -d "$DIR" ]]; then\n  echo "Error: $DIR is not a directory" >&2\n  exit 1\nfi\n\n# Count files (regular files only)\nfile_count=$(find "$DIR" -type f | wc -l | tr -d ' ')\n# Total size in bytes\nif command -v find >/dev/null 2>&1 && find "$DIR" -type f -printf "%s\n" >/dev/null 2>&1; then\n  total_bytes=$(find "$DIR" -type f -printf "%s\n" | awk '{sum+=$1} END {print sum}')\nelse\n  total_bytes=$(find "$DIR" -type f -exec stat -c %s {} + | awk '{sum+=$1} END {print sum}')\nfi\n# Human readable size\nif command -v numfmt >/dev/null 2>&1; then\n  human_size=$(numfmt --to=iec-i --suffix=B "$total_bytes")\nelse\n  human_size="${total_bytes}B"\nfi\n\n# Determine most common extension\next=$(find "$DIR" -type f -name "*.*" -printf "%f\n" | rev | cut -d. -f1 | rev | tr '[:upper:]' '[:lower:]' | sort | uniq -c | sort -nr | head -n1 | awk '{print $2}')\nif [[ -z "$ext" ]]; then\n  ext="none"\nelse\n  ext=".$ext"\nfi\n\n# Choose mood emoji based on size thresholds\nif (( total_bytes < 1048576 )); then\n  emoji="😊"\nelif (( total_bytes < 1073741824 )); then\n  emoji="😎"\nelse\n  emoji="🤯"\nfi\n\necho "📂 Scanned $file_count files, total size $human_size, most common type: $ext $emoji"
